const item = $input.first().json;

let startIso = item.start_iso || '';
let endIso = item.end_iso || '';
const duracaoMinutos = Number(item.duracao_minutos) || 30;

// Garante o formato ISO com fuso horários se vier em data simples
if (startIso && !startIso.includes('T')) {
  startIso = `${startIso}T00:00:00-03:00`;
}

// Se o fim não for informado ou for igual ao início, calcula fim = início + duração
if (!endIso || endIso === startIso) {
  if (startIso) {
    const startDate = new Date(startIso);
    if (!isNaN(startDate.getTime())) {
      const endDate = new Date(startDate.getTime() + duracaoMinutos * 60000);

      const tzOffsetMs = -3 * 60 * 60 * 1000; // -03:00
      const localEnd = new Date(endDate.getTime() + tzOffsetMs);

      const yyyy = localEnd.getUTCFullYear();
      const mm = String(localEnd.getUTCMonth() + 1).padStart(2, '0');
      const dd = String(localEnd.getUTCDate()).padStart(2, '0');
      const hh = String(localEnd.getUTCHours()).padStart(2, '0');
      const min = String(localEnd.getUTCMinutes()).padStart(2, '0');

      endIso = `${yyyy}-${mm}-${dd}T${hh}:${min}:00-03:00`;
    }
  }
}

return [{
  json: {
    ...item,
    start_iso: startIso,
    end_iso: endIso
  }
}];

const googleResp = $input.first().json;

const isError = googleResp.error !== undefined || 
                googleResp.statusCode >= 400 || 
                !googleResp.id;

if (isError) {
  const msgErro = googleResp.error?.message || 
                  googleResp.message || 
                  "Agendamento não encontrado no Google Calendar ou ID do evento é inválido.";
  return [{
    json: {
      sucesso: false,
      mensagem: `Falha ao atualizar no Google Calendar: ${msgErro}`
    }
  }];
}

return [{
  json: {
    sucesso: true,
    mensagem: "Agendamento alterado com sucesso!",
    event_id: googleResp.id,
    start: googleResp.start?.dateTime,
    end: googleResp.end?.dateTime
  }
}];
